// Planner → a repo's deploy card, AS GRAPH SOURCE (#4230, epic #3604). Transcribed from the live feature file. Its
// `provides: "@/features/planner/bodies/DeployView"` makes the runtime loader vendor THIS source wherever a graph
// component imports that specifier — so the stage-body switch reaches it from the graph without
// knowing it, and the registered module stays as the fallback. Behaviour runs here.
// Deploy stage pane (#919, redesign per design/Base studio code deployment) — the focused-pane
// body for the planner's Deploy stage (right after Repos). Pure presentational: reads a DeployConfig
// (+ the locked dependency manifest) and calls onChange with the next config. The `deploymentDefined`
// gate signal is derived from the same deployChecks(); a card turns green once its check passes.
//
// Structure mirrors the design: A · HOW IT SHIPS (target+hosting · pipeline · environments ·
// config+secrets) → B · WHAT IT DEPENDS ON (dependencies, grouped by source) → C · RELEASE & HEALTH
// → D · READINESS (checklist + the stream:deploy issues this config generates at publish).
//
// Split into focused modules (#1636): the Deploy-local form primitives live in `deployPrimitives`,
// the target editor (Cloud/Local picker) in `deployTargetSection`, and the per-repo ship sections
// (pipeline · environments · config · rollout) in `deployShipSections`. This file is now the
// composition shell — the per-repo card and the top-level body that owns the open/expand state.

import type { DeployService } from "@/features/planner/lib/deployConfig";
import { MONO } from "@/features/planner/bodies/bodyStyles";
import { chip } from "@/features/planner/bodies/deployPrimitives";
import { ServiceTargetEditor } from "@/features/planner/bodies/deployTargetSection";
import { ServiceDeploySections } from "@/features/planner/bodies/deployShipSections";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Re-exported for API compatibility (#1636) — these moved to focused modules but keep their old
// import path here so existing consumers (ReposDeployView, tests) and any external imports work.
export { Card, Divider } from "@/features/planner/bodies/deployPrimitives";
export { ServiceTargetEditor } from "@/features/planner/bodies/deployTargetSection";
export { ServiceDeploySections } from "@/features/planner/bodies/deployShipSections";

// `@/features/planner/lib/deployConfig` pulls in `features/planner/lib/deployEnv`, which fails to
// build in this preview sandbox (a genuine syntax error in that app-internal file, outside this kit's
// `bsc ui` surface). Importing its exports as VALUES crashes the whole module at load time; these
// local stand-ins replace the three runtime values this file itself needs. `DeployService` above
// stays `import type` (erased at build time, safe).
const WORKLOAD: Record<string, { c: string; label: string }> = {
  static: { c: "var(--info)", label: "static" },
  container: { c: "var(--violet)", label: "container" },
  serverless: { c: "var(--accent)", label: "serverless" },
};
const PLATFORMS = [
  { id: "vercel", h: 265, glyph: "▲", name: "Vercel" },
  { id: "fly", h: 300, glyph: "◆", name: "Fly.io" },
  { id: "aws", h: 40, glyph: "▣", name: "AWS" },
];
function platform(id: string) { return PLATFORMS.find((p) => p.id === id) ?? { id: "", h: 0, glyph: "▢", name: "" }; }
function serviceMode(svc: DeployService): string { return (svc.mode as string) ?? "cloud"; }
function serviceTargetDefined(svc: DeployService): boolean {
  return serviceMode(svc) === "cloud" ? !!svc.platform : !!svc.localKind;
}
function serviceReady(svc: DeployService): boolean { return serviceTargetDefined(svc) && serviceMode(svc) === "cloud"; }

const DEFAULT_SVC: DeployService = {
  id: "svc1", repo: "acme/design-studio", platform: "vercel", workload: "static", mode: "cloud",
  pipeline: { provider: "GitHub Actions", stages: [
    { id: "s1", name: "lint", gate: false, cmd: "npm run lint", trigger: "push" },
    { id: "s2", name: "test", gate: true, cmd: "npm test", trigger: "push" },
    { id: "s3", name: "deploy", gate: false, cmd: "vercel deploy --prod", trigger: "push" },
  ] },
  envs: [
    { id: "preview", name: "preview", auto: true, branch: "*", url: "" },
    { id: "prod", name: "prod", auto: false, branch: "main", url: "design-studio.app" },
  ],
  config: { vault: "1Password", config: [{ key: "API_URL", preview: "https://api-preview…", prod: "https://api…" }], secrets: [{ key: "DB_PASSWORD", preview: "", prod: "" }] },
  release: { strategy: "rolling", autoRollback: true, migrateWithDeploy: false },
  health: { probeOn: true, probe: "/healthz" },
} as unknown as DeployService;
const NOOP = () => {};

/** One collapsible per-repo deployment card (#1421) — the unit of the new design. Collapsed row =
 *  status · id · target · workload · ready/✓ · chevron; expanded = the target editor + (once a
 *  target is set) the repo's ship sections. `lead` lets the merged Repos & Deployment pane inject
 *  the repo's git identity row. */
export function RepoDeployCard({ svc = DEFAULT_SVC, setSvc = NOOP, open = true, onToggle = NOOP, lead, meta, trailing }: {
  svc?: DeployService; setSvc?: (patch: Partial<DeployService>) => void;
  open?: boolean; onToggle?: () => void; lead?: React.ReactNode;
  /** Collapsed-row identity extras shown after the repo name (language · ahead/behind · agents) —
   *  the merged Repositories & Deployment pane folds the repo's git identity in here. */
  meta?: React.ReactNode;
  /** Collapsed-row trailing slot before the chevron (e.g. the per-repo visibility toggle). */
  trailing?: React.ReactNode;
}) {
  const targeted = serviceTargetDefined(svc);
  const ready = serviceReady(svc);
  const local = serviceMode(svc) === "local";
  const p = svc.platform ? platform(svc.platform) : null;
  const dot = ready ? "var(--success)" : targeted ? "var(--accent)" : "var(--warn)";
  return (
    <Box bg="var(--bg-elev)" radius="lg" style={{ border: "1px solid " + (open ? "var(--accent-dim)" : "var(--border-soft)"), overflow: "hidden" }}>
      <Row onClick={onToggle} gap={9} style={{ padding: "11px 13px", cursor: "pointer", userSelect: "none" }}>
        <Box as="span" bg={dot} radius={99} style={{ width: 7, height: 7, flex: "0 0 7px", boxShadow: ready ? `0 0 7px color-mix(in oklch, ${dot}, transparent 60%)` : undefined }} />
        <Text as="span" mono size={12} style={{ color: "var(--fg)" }}>{svc.repo || svc.id}</Text>
        {meta}
        <Spacer />
        {targeted ? (
          <>
            <Box as="span" style={{ ...chip, color: local ? "var(--violet)" : "var(--accent)", borderColor: local ? "color-mix(in oklch, var(--violet), transparent 60%)" : "var(--accent-dim)", background: `color-mix(in oklch, ${local ? "var(--violet)" : "var(--accent)"}, transparent 86%)` }}>
              {local ? `⬢ ${svc.localKind ?? "local"}` : <>{p && <Text as="span" style={{ color: `oklch(0.78 0.12 ${p.h})` }}>{p.glyph} </Text>}{p?.name}</>}
            </Box>
            {!local && <Box as="span" style={{ ...chip, fontSize: 8, color: WORKLOAD[svc.workload].c, borderColor: `color-mix(in oklch, ${WORKLOAD[svc.workload].c}, transparent 60%)` }}>{WORKLOAD[svc.workload].label}</Box>}
            <Box as="span" bg={ready ? "color-mix(in oklch, var(--success), transparent 84%)" : "var(--bg-elev2)"} radius={99} style={{ width: 18, height: 18, display: "inline-flex", alignItems: "center", justifyContent: "center", fontFamily: MONO, fontSize: 10, color: ready ? "var(--success)" : "var(--fg-dim)"}}>{ready ? "✓" : "·"}</Box>
          </>
        ) : (
          <Box as="span" style={{ ...chip, color: "var(--warn)", borderColor: "color-mix(in oklch, var(--warn), transparent 55%)", background: "transparent", borderStyle: "dashed" }}>set target →</Box>
        )}
        {trailing}
        <Text as="span" mono size={11} tone="dim" style={{ width: 12, textAlign: "center" }}>{open ? "▾" : "▸"}</Text>
      </Row>
      {open && (
        <Stack gap={12} style={{ borderTop: "1px solid var(--border-soft)", padding: "12px 13px" }}>
          {lead}
          <ServiceTargetEditor svc={svc} setSvc={setSvc} />
          {targeted && <ServiceDeploySections svc={svc} setSvc={setSvc} />}
        </Stack>
      )}
    </Box>
  );
}
